import React from "react";
import AccelLogo from "assets/img/accel_logo.png"; // adapte le chemin si besoin

export default function Footer() {
  return (
    <footer className="bg-[#20264e] text-white">
      <div className="max-w-7xl mx-auto px-6 lg:px-10 py-16">
        {/* grille 3 colonnes */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-12">
          {/* Powered by */}
          <div>
            <h3 className="text-3xl font-extrabold tracking-wide mb-8">Powered By</h3>
            <img
              src={AccelLogo}
              alt="Accel"
              className="h-24 w-auto select-none"
            />
          </div>

          {/* Liens utiles */}
          <div>
            <h3 className="text-3xl font-extrabold tracking-wide mb-8">Liens utiles</h3>
            <ul className="space-y-6 text-2xl md:text-2xl/relaxed font-light">
              {[
                { label: "Red Hat Enterprise Linux", href: "#" },
                { label: "Openshift AI", href: "#" },
                { label: "Heritage Cloud", href: "#" },
              ].map((l, i) => (
                <li key={i} className="flex items-start gap-4">
                  <i className="fa-solid fa-link text-blue-200 text-2xl mt-1" />
                  <a
                    href={l.href}
                    className="hover:underline underline-offset-4"
                  >
                    {l.label}
                  </a>
                </li>
              ))}
            </ul>
          </div>

          {/* Contacts */}
          <div>
            <h3 className="text-3xl font-extrabold tracking-wide mb-8">Contacts</h3>
            <ul className="space-y-6 text-2xl md:text-2xl/relaxed font-light">
              <li className="flex items-center gap-4">
                <i className="fa-solid fa-phone text-blue-200 text-2xl" />
                <span>33.000.000.00</span>
              </li>
              <li className="flex items-center gap-4">
                <i className="fa-regular fa-envelope text-blue-200 text-2xl" />
                <a href="mailto:xxx@example.com" className="hover:underline">
                  xxx@example.com
                </a>
              </li>
              <li className="flex items-center gap-4">
                <i className="fa-solid fa-globe text-blue-200 text-2xl" />
                <a href="#" className="hover:underline">
                  www.example.com
                </a>
              </li>
            </ul>
          </div>
        </div>

        {/* ligne d’icônes sociales */}
        <div className="mt-14 flex items-center justify-center gap-16">
          <a href="#" aria-label="Facebook" className="group">
            <i className="fa-brands fa-facebook-f text-[#F05A28] text-3xl group-hover:opacity-80 transition" />
          </a>
          <a href="#" aria-label="LinkedIn" className="group">
            <i className="fa-brands fa-linkedin-in text-[#F05A28] text-3xl group-hover:opacity-80 transition" />
          </a>
          <a href="#" aria-label="YouTube" className="group">
            <i className="fa-brands fa-youtube text-[#F05A28] text-3xl group-hover:opacity-80 transition" />
          </a>
        </div>
      </div>
    </footer>
  );
}
